/*
 * A258129  Octagonal numbers (A000567) that are the sum of three consecutive
 *          octagonal numbers.
 * https://oeis.org/A258129
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = Oct(t) = 3t²‑2t, where t is the n‑th integer for which
 *            the equation k²‑3v²=16 has a solution with k≡v≡2 (mod 3) and k =
 *            3t‑1. The solutions (k,v) are generated by the Pell recurrence
 *            u_{n+1}=2u_n+3v_n, v_{n+1}=u_n+2v_n, starting from (8,4)
 * Range:     u8 none, u16 none, u32 n <= 1, u64 n <= 2, u128 n <= 5,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The function is memoised; it works for any implementation of seq_t
   and idx_t that supports the operators used below. */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Cache of already computed terms; 1‑indexed. */
    static seq_t *cache = NULL;
    static size_t capacity = 0;           /* allocated array size (>= n+1) */
    static size_t cached_terms = 0;       /* number of terms stored (>= cached_terms >= n on return) */

    /* Current state of the Pell recurrence. */
    static seq_t cur_u = 8;               /* u (k) */
    static seq_t cur_v = 4;               /* v */
    static size_t pell_step = 0;          /* step index of cur_u,cur_v (0 start) */

    /* Ensure the cache can hold the requested index. */
    if (n + 1 > capacity) {
        size_t new_cap = n + 1;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        cache = tmp;
        capacity = new_cap;
    }

    /* Generate new terms until we have at least n of them. */
    while (cached_terms < n) {
        /* Check whether current (u,v) satisfies k≡v≡2 (mod 3). */
        if ( (cur_u % 3) == 2 && (cur_v % 3) == 2 ) {
            /* Compute t = (u+1)/3 and the octagonal number Oct(t). */
            seq_t t   = (cur_u + 1) / 3;
            seq_t tmp = 3 * t - 2;   /* 3t‑2 */
            seq_t oct = tmp * t;     /* 3t²‑2t */

            /* Store the term (1‑indexed). */
            cache[++cached_terms] = oct;
        }

        /* Advance the Pell recurrence to the next solution. */
        seq_t next_u = 2 * cur_u + 3 * cur_v;
        seq_t next_v = cur_u + 2 * cur_v;
        cur_u = next_u;
        cur_v = next_v;
        ++pell_step;
    }

    return cache[n];
}
